import { resolveAstV2MeaningItems } from './meaning-resolver-production-ast-v2.js';
import { sha256Canonical } from './meaning-resolver-production.js';
function freeze(v){if(v&&typeof v==='object'&&!Object.isFrozen(v)){Object.freeze(v);for(const x of Object.values(v))freeze(x)}return v;}
export async function buildAstV2CanonicalMeaningProductionBundle({projection,admissionRegistry,mappingRegistry,activationRegistry}={}){
 const r=await resolveAstV2MeaningItems({projection,admissionRegistry,mappingRegistry,activationRegistry,mode:'production'}); const registryVersions={admissionRegistryVersion:admissionRegistry.schemaVersion,mappingRegistryVersion:mappingRegistry.schemaVersion}; const bundleDigest=await sha256Canonical({projectionDigest:r.projectionDigest,registryVersions,matchedMappingCodes:r.items.map(x=>x.mappingLineage.mappingCode).sort(),meaningIdentityDigests:r.items.map(x=>x.evidence.meaningCanonicalDigest).sort()});
 return freeze({schemaVersion:'PHI-OS-CANONICAL-MEANING-PRODUCTION-BUNDLE-v1.0.0',bundleCode:`CMPB-${bundleDigest.slice(0,24).toUpperCase()}`,bundleVersion:'1.0.0',status:'PRODUCTION',activationState:'PRODUCTION_ACTIVE',sourceProjection:{projectionId:projection.projectionId,schemaVersion:projection.schemaVersion,publicMethodCode:r.publicMethodCode,methodCode:r.methodCode,projectionDigest:r.projectionDigest},registryVersions,items:[...r.items],bundleDigest,boundaries:{providerUsed:false,aiUsed:false,promptUsed:false,recalculated:false,projectionMutated:false,interpretationCreated:false,professionalJudgmentCreated:false,realityDecisionCreated:false,localeRenderingIncluded:false}});
}
